selected.compute:
options = read('/input/options')
ids = [item['id'] for item in options]
result = []
for count in range(goal['min_count'], goal['max_count'] + 1):
    for choice in combinations(ids, count):
        candidate = list(choice)
        if valid(candidate):
            result = candidate
            break
    if result:
        break

selected.effects:
existing = read('/output/selection')
if existing:
    if valid(existing):
        result = existing
    else:
        result = []
if not exists('/output/selection'):
    if result and valid(result):
        write('/output/selection', result)
if result and valid(result):
    delivery = receipt('report')
    if delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'unknown':
        state = status('report')
    elif delivery == 'failure':
        send('report', 'team', result)
